#[test]
fn read_only_saved_snapshot_can_coexist_with_editor_writer() {
    let (_directory, path) = project();
    let editor = engine_project_lifecycle::acquire_editor_project(&path)
        .expect("Editor lease");
    let host = HeadlessAuthoringHost::open_read_only(
        &path,
        HeadlessProjectSelection::default(),
    )
    .expect("read-only host");
    assert_eq!(host.access_mode(), HeadlessAccessMode::ReadOnlySavedFiles);
    assert!(!host.view_descriptor().live_editor_unsaved_state_visible);
    assert!(HeadlessAuthoringHost::open_writer(
        &path,
        HeadlessProjectSelection::default(),
    )
    .is_err());
    drop(host);
    drop(editor);
}

